import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { Layout, Menu, Button, Modal, Form, Input, Checkbox, Switch } from 'antd';
import { UserOutlined, HomeOutlined } from '@ant-design/icons';
import './App.css';  // Можеш додати свої стилі тут

const { Header, Content, Sider } = Layout;
const CheckboxGroup = Checkbox.Group;

// Модальне вікно авторизації
const AuthModal = () => {
  const [visible, setVisible] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleLogin = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setVisible(false);
    }, 2000);
  };

  return (
    <>
      <Button type="primary" onClick={() => setVisible(true)}>
        Авторизуватись
      </Button>
      <Modal
        visible={visible}
        onCancel={() => setVisible(false)}
        footer={null}
      >
        <Form onFinish={handleLogin}>
          <Form.Item label="Користувач" name="username">
            <Input />
          </Form.Item>
          <Form.Item label="Пароль" name="password">
            <Input.Password />
          </Form.Item>
          <Form.Item>
            <Button type="primary" htmlType="submit" loading={loading}>
              Увійти
            </Button>
          </Form.Item>
        </Form>
      </Modal>
    </>
  );
};

// Компонент кнопок
const Buttons = () => (
  <div>
    <Button type="primary" style={{ backgroundColor: '#1890ff', borderColor: '#1890ff' }}>
      Primary Blue
    </Button>
    <Button type="primary" style={{ backgroundColor: '#ff4d4f', borderColor: '#ff4d4f' }}>
      Primary Red
    </Button>
    <Button type="default">Default</Button>
    <Button type="dashed">Dashed</Button>
  </div>
);

// Компонент для чекбоксів з кнопкою "Обрати всі"
const CheckboxList = () => {
  const options = ['Option 1', 'Option 2', 'Option 3'];
  const [checkedList, setCheckedList] = useState([]);

  const selectAll = () => {
    setCheckedList(options);
  };

  return (
    <div>
      <CheckboxGroup options={options} value={checkedList} onChange={setCheckedList} />
      <Button type="primary" onClick={selectAll}>
        Обрати всі
      </Button>
    </div>
  );
};

const ThemeSwitcher = () => {
  const [darkMode, setDarkMode] = useState(false);

  const toggleTheme = () => {
    setDarkMode(prevMode => {
      const newMode = !prevMode;
      document.body.style.backgroundColor = newMode ? '#333' : '#fff';
      document.body.style.color = newMode ? '#fff' : '#000';
      return newMode;
    });
  };

  return (
    <div>
      <Switch 
        checkedChildren="Темна" 
        unCheckedChildren="Світла" 
        checked={darkMode} 
        onChange={toggleTheme} 
      />
    </div>
  );
};

// Сторінка адміністратора
const AdminPage = () => (
  <Layout>
    <Sider>
      <Menu>
        <Menu.Item key="1" icon={<UserOutlined />}>
          <Link to="/admin">Адмін-панель</Link>
        </Menu.Item>
      </Menu>
    </Sider>
    <Layout>
      <Header>Адмін панель</Header>
      <Content>
        <p>Тут інформація для адміністратора</p>
        <AuthModal />
        <Buttons />
        <CheckboxList />
      </Content>
    </Layout>
  </Layout>
);

// Головна сторінка
const HomePage = () => (
  <Layout>
    <Sider>
      <Menu>
        <Menu.Item key="1" icon={<HomeOutlined />}>
          <Link to="/">Головна</Link>
        </Menu.Item>
      </Menu>
    </Sider>
    <Layout>
      <Header>Головна сторінка</Header>
      <Content>
        <p>Тут основний контент сайту</p>
        <ThemeSwitcher />
      </Content>
    </Layout>
  </Layout>
);

// Головний компонент App
const App = () => (
  <Router>
    <Routes>
      <Route path="/admin" element={<AdminPage />} />
      <Route path="/" element={<HomePage />} />
    </Routes>
  </Router>
);

export default App;
